import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import { Button, Menu, Dropdown, Icon, Form, DatePicker, Select, Row, Col, Input, Alert, Checkbox } from 'antd'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import LayoutContent from '../../../components/utility/layoutContent'
import promoAction from '../../redux/promo/actions'
import validator from '../../../helpers/validator'
import moment from 'moment'

const FormItem = Form.Item
const { Option } = Select

const { createPromo, updatePromo } = promoAction

class PromoDetails extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      createPromo: false,
      editPromo: false,
      data: undefined
    }
  }

  componentWillMount = () => {
    const { params } = this.props.history.location.state
    this.setState({ createPromo: params.createPromo, data: params.data })
  }
  renderCreatePromoForm = () => {
    const { form } = this.props
    const { getFieldDecorator } = form
    return (
      <Form onSubmit={this.onSubmit}>
        <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
          <Col xs={6}>
            <label className='custom-label'>Name</label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('name', {
                rules: [
                  { required: true, message: 'Name can not be empty' },
                  { validator: validator.validateCode }
                ]
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </Col>
          <Col xs={6}>
            <label className='custom-label'><b>Description</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('description', {
                rules: [
                  { required: true, message: 'Description can not be empty' },
                  { validator: validator.validateDescription }
                ]
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </Col>
          <Col xs={6}>
            <label className='custom-label'><b>Start Date and Time</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('start_date', {
                rules: [
                  { required: true, message: 'Start Date and Time can not be empty' }
                ]
              })(
                <DatePicker
                  showTime
                  format='YYYY-MM-DD HH:mm:ss'
                />
              )}
            </FormItem>
          </Col>
          <Col xs={6}>
            <label className='custom-label'><b>End Date and Time</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('end_date', {
                rules: [
                  { required: true, message: 'End Date and Time can not be empty' }
                ]
              })(
                <DatePicker
                  showTime
                  format='YYYY-MM-DD HH:mm:ss'
                />
              )}
            </FormItem>
          </Col>
        </Row>
        <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
          <Col xs={6}>
            <label className='custom-label'><b>Discount Type</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('discount_type', {
                rules: [
                  { required: true, message: 'please select Discount Type' }
                ]
              })(
                <Select>
                  <Option value='PERCENTAGE'>PERCENTAGE</Option>
                  <Option value='ABSOLUTE'>ABSOLUTE</Option>
                </Select>
              )}
            </FormItem>
          </Col>
          <Col xs={6}>
            <label className='custom-label'><b>Discount Value</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('discount_value', {
                rules: [
                  { required: true, message: 'Discount Value can not be empty' }
                ]
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </Col>
          <Col xs={6}>
            <label className='custom-label'><b>Minimum Premium</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('minimum_premium', {
                rules: [
                  { required: true, message: 'Minimum Premium can not be empty' }
                ]
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </Col>
          <Col xs={6}>
            <label className='custom-label'><b>Maximum Premium</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('maximum_premium', {
                rules: [
                  { required: true, message: 'Maximum Premium can not be empty' }
                ]
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </Col>
        </Row>
        <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
          <Col xs={6}>
            <label className='custom-label'><b>Max Discount Availed through Coupon</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('maximum_discount_amount', {
                rules: [
                  { required: true, message: 'Max Discount Availed through Coupon can not be empty' }
                ]
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </Col>
          <Col xs={6}>
            <label className='custom-label'><b>Total Discount Availed through Coupon</b></label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('total_maximum_discount_allowed', {
                rules: [
                  { required: true, message: 'Total Discount Availed through Coupon can not be empty' }
                ]
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </Col>
        </Row>
        <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
          <Col xs={6}>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('is_active', {
                rules: [
                  { required: true, message: 'Checbox can not be empty' }
                ],
                defaultValue: false
              })(
                <Checkbox>Is Active</Checkbox>
              )}
            </FormItem>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator('autoapply', {
                rules: [
                  { required: true, message: 'Checbox can not be empty' }
                ],
                defaultValue: false
              })(
                <Checkbox >Auto Apply</Checkbox>
              )}
            </FormItem>
          </Col>
        </Row>
      </Form>
    )
  }

  renderEditPromoForm = () => {
    const { form } = this.props
    const { getFieldDecorator } = form
    const { data } = this.state
    const activeCoupons = this.state.data.active_coupons
    let activeCouponsMenu = activeCoupons.map(
      (d) => <Menu.Item key={d.coupon_id}>
        <p>{d.coupon_code}</p>
      </Menu.Item>
    )

    const menu = (
      <Menu>
        {activeCouponsMenu}
      </Menu>
    )

    if (!this.state.editPromo) {
      return (
        <div>
          {this.props.promoData.promoMessage === 'successfully updated' && (
            <Row style={{ width: '100%' }}>
              <Col span={24}>
                <Alert
                  style={{ marginBottom: '20px' }}
                  message={this.props.promoData.promoMessage}
                  type='success'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          {this.props.promoData.promoMessage === 'failed to update promo' && (
            <Row style={{ width: '100%' }}>
              <Col span={24}>
                <Alert
                  style={{ marginBottom: '20px' }}
                  message={this.props.promoData.promoMessage}
                  type='error'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <label><b>Name</b></label>
              <p>{data.name}</p>
            </Col>
            <Col xs={6}>
              <label><b>Description</b></label>
              <p>{data.description}</p>
            </Col>
            <Col xs={6}>
              <label><b>Start Date and Time</b></label>
              <p>{data.start_date}</p>
            </Col>
            <Col xs={6}>
              <label><b>End Date and Time</b></label>
              <p>{data.end_date}</p>
            </Col>
          </Row>
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <label><b>Discount Type</b></label>
              <p>{data.discount_type}</p>
            </Col>
            <Col xs={6}>
              <label><b>Discount Value</b></label>
              <p>{data.discount_value}</p>
            </Col>
            <Col xs={6}>
              <label><b>Min Premium Amount</b></label>
              <p>{data.minimum_premium}</p>
            </Col>
            <Col xs={6}>
              <label><b>Maximum Premium Amount</b></label>
              <p>{data.maximum_premium}</p>
            </Col>
          </Row>
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <label><b>Max Discount Availed through Coupon</b></label>
              <p>{data.maximum_discount_amount}</p>
            </Col>
            <Col xs={6}>
              <label><b>Total Discount Availed through Coupon</b></label>
              <p>{data.total_maximum_discount_allowed}</p>
            </Col>
            <Col xs={6}>
              <p>
                <Dropdown overlay={menu}>
                  <Button style={{ marginLeft: 8 }}>
                Active Coupons <Icon type='down' />
                  </Button>
                </Dropdown>
              </p>
            </Col>
          </Row>
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <p>Is Active: {data.is_active ? <Icon type='check-circle' style={{ fontSize: '16px', color: '#008000' }} theme='outlined' /> : <Icon type='close-circle' style={{ fontSize: '16px', color: 'red' }} theme='outlined' />}</p>
              <p>Auto Apply: {data.autoapply ? <Icon type='check-circle' style={{ fontSize: '16px', color: '#008000' }} theme='outlined' /> : <Icon type='close-circle' style={{ fontSize: '16px', color: 'red' }} theme='outlined' />}</p>
            </Col>
          </Row>
        </div>
      )
    } else {
      return (
        <Form onSubmit={this.onSubmit}>
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <label className='custom-label'>Name</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('name', {
                  rules: [
                    { required: true, message: 'Name can not be empty' },
                    { validator: validator.validateCode }
                  ],
                  initialValue: data.name
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </Col>
            <Col xs={6}>
              <label className='custom-label'><b>Description</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('description', {
                  rules: [
                    { required: true, message: 'Description can not be empty' },
                    { validator: validator.validateDescription }

                  ],
                  initialValue: data.description
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </Col>
            <Col xs={6}>
              <label className='custom-label'><b>Start Date and Time</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('start_date', {
                  rules: [
                    { required: true, message: 'Start Date and Time can not be empty' }
                  ],
                  initialValue: moment(data.start_date)
                })(
                  <DatePicker
                    defaultPickerValue={moment(data.start_date, 'yyyy-mm-dd HH:mm:ss')}
                    showTime
                    format='YYYY-MM-DD HH:mm:ss'
                  />
                )}
              </FormItem>
            </Col>
            <Col xs={6}>
              <label className='custom-label'><b>End Date and Time</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('end_date', {
                  rules: [
                    { required: true, message: 'End Date and Time can not be empty' }
                  ],
                  initialValue: moment(data.end_date)
                })(
                  <DatePicker
                  defaultPickerValue={moment(data.start_date, 'yyyy-mm-dd HH:mm:ss')}
                    showTime
                    format='YYYY-MM-DD HH:mm:ss'
                  />
                )}
              </FormItem>
            </Col>
          </Row>
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <label className='custom-label'><b>Discount Type</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('discount_type', {
                  rules: [
                    { required: true, message: 'please select Discount Type' }
                  ],
                  initialValue: data.discount_type
                })(
                  <Select>
                    <Option value='PERCENTAGE'>PERCENTAGE</Option>
                    <Option value='ABSOLUTE'>ABSOLUTE</Option>
                  </Select>
                )}
              </FormItem>
            </Col>
            <Col xs={6}>
              <label className='custom-label'><b>Discount Value</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('discount_value', {
                  rules: [
                    { required: true, message: 'Discount Value can not be empty' }
                  ],
                  initialValue: data.discount_value
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </Col>
            <Col xs={6}>
              <label className='custom-label'><b>Minimum Premium</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('minimum_premium', {
                  rules: [
                    { required: true, message: 'Minimum Premium can not be empty' }
                  ],
                  initialValue: data.minimum_premium
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </Col>
            <Col xs={6}>
              <label className='custom-label'><b>Maximum Premium</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('maximum_premium', {
                  rules: [
                    { required: true, message: 'Maximum Premium can not be empty' }
                  ],
                  initialValue: data.maximum_premium
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </Col>
          </Row>
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <label className='custom-label'><b>Max Discount Availed through Coupon</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('maximum_discount_amount', {
                  rules: [
                    { required: true, message: 'Max Discount Availed through Coupon can not be empty' }
                  ],
                  initialValue: data.maximum_discount_amount
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </Col>
            <Col xs={6}>
              <label className='custom-label'><b>Total Discount Availed through Coupon</b></label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('total_maximum_discount_allowed', {
                  rules: [
                    { required: true, message: 'Total Discount Availed through Coupon can not be empty' }
                  ],
                  initialValue: data.total_maximum_discount_allowed
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </Col>
          </Row>
          <Row type='flex' justify='start' gutter={40} style={{ padding: '20px 0px' }}>
            <Col xs={6}>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('is_active', {
                  rules: [
                    { required: true, message: 'Checbox can not be empty' }
                  ],
                  initialValue: data.is_active
                })(
                  <Checkbox defaultChecked={data.is_active}>Is Active</Checkbox>
                )}
              </FormItem>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('autoapply', {
                  rules: [
                    { required: true, message: 'Checbox can not be empty' }
                  ],
                  initialValue: data.autoapply
                })(
                  <Checkbox defaultChecked={data.autoapply}>Auto Apply</Checkbox>
                )}
              </FormItem>
            </Col>
          </Row>
        </Form>
      )
    }
  }
  onSubmit = () => {

  }
  onEdit = () => {
    this.setState({ editPromo: true })
  }
  onCancel = () => {
    this.setState({ editPromo: false })
  }
  onCreateCancel = () => {
    this.props.promoData.createPromoMessage = undefined
    this.props.history.goBack()
  }

  onBackClicked = () => {
    this.props.history.goBack()
  }

  onCreate= () => {
    const { form } = this.props
    const data = form.getFieldsValue()
    data.start_date = moment(data.start_date).format('YYYY-MM-DD HH:mm:ss')
    data.end_date = moment(data.end_date).format('YYYY-MM-DD HH:mm:ss')
    this.props.createPromo(data)

    // if (this.props.promoData.createPromoMessage === 'success') {
    //   this.props.history.goBack()
    // }
  }
  onSave = () => {
    const { form } = this.props
    const data = form.getFieldsValue()
    data.id = this.state.data.id
    data.start_date = moment(data.start_date).format('YYYY-MM-DD HH:mm:ss')
    data.end_date = moment(data.end_date).format('YYYY-MM-DD HH:mm:ss')
    this.props.updatePromo(data)
    this.setState((prevState) => ({
      data: {
        ...prevState.data,
        is_active: data.is_active,
        autoapply: data.autoapply
      },
      editPromo: false
    }))
  }
  render () {
    let promoUI = ''
    if (this.state.createPromo) {
      promoUI = this.renderCreatePromoForm()
    } else {
      promoUI = this.renderEditPromoForm()
    }
    setTimeout(() => {
      if (this.props.promoData.promoMessage === 'success' || this.props.promoData.createPromoMessage === 'success') {
        this.props.history.goBack()
      }
      this.props.promoData.promoMessage = undefined
    }, 100)

    return (
      <LayoutContentWrapper>
        <LayoutContent>
          {this.props.promoData.createPromoMessage === 'success' && (
            <Row className='error-row'>
              <Col span={24}>
                <Alert
                  className='alert'
                  message={this.props.promoData.createPromoMessage}
                  type='success'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          {this.props.promoData.createPromoMessage !== 'success' && this.props.promoData.createPromoMessage !== undefined && (
            <Row className='error-row'>
              <Col span={24}>
                <Alert
                  className='alert'
                  message={this.props.promoData.createPromoMessage}
                  type='error'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          <h3><b>Promotion details</b></h3>
          {promoUI}
          <Row type='flex' justify='end' style={{ padding: '20px 0px' }}>
            {this.state.editPromo && <Col xs={2}>
              <Button onClick={this.onCancel}>Cancel</Button>
            </Col> }
            {this.state.createPromo && <Col xs={2}>
              <Button onClick={this.onCreateCancel}>Cancel</Button>
            </Col> }
            {this.state.createPromo && <Col xs={2}>
              <Button type='primary' onClick={this.onCreate}>Create</Button>
            </Col>
            }
            {this.state.editPromo && <Col xs={2}>
              <Button type='primary' onClick={this.onSave}>Save</Button>
            </Col>
            }
            {!this.state.editPromo && !this.state.createPromo && <Col xs={2}>
              <Button type='primary' onClick={this.onBackClicked}>Back</Button>
            </Col>
            }
            {!this.state.editPromo && !this.state.createPromo && <Col xs={2}>
              <Button type='primary' onClick={this.onEdit}>Edit</Button>
            </Col>
            }

          </Row>
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

const WrappedForm = Form.create({})(PromoDetails)

export default connect(
  state => ({
    promoData: state.PromoDetails
  }),
  { createPromo, updatePromo }
)(WrappedForm)
